local OvenPeelMaker = {}
local PRODUCTS = {
    iron_ovenpeel = { name = "Železni pekovska lopata", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni pekovska lopata za pekarno." },
    bronze_ovenpeel = { name = "Bronast pekovska lopata", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast pekovska lopata za pekarno." },
    silver_ovenpeel = { name = "Srebrn pekovska lopata", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn pekovska lopata za pekarno." },
    gilded_ovenpeel = { name = "Pozlačen pekovska lopata", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen pekovska lopata za pekarno." },
    jewel_set_ovenpeel = { name = "Draguljast pekovska lopata", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast pekovska lopata za pekarno." },
    royal_sovereign_ovenpeel = { name = "Kraljevski suveren pekovska lopata", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren pekovska lopata z biseri za krono." },
}
local BUILDINGS = {
    ovenpeel_workshop = { name = "Ovenpeel delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    ovenpeel_house = { name = "Ovenpeel hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_ovenpeel_atelier = { name = "Mojstrski ovenpeel atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_ovenpeel_palace = { name = "Suverena ovenpeel palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
OvenPeelMaker.ironStock = 12; OvenPeelMaker.bronzeStock = 10; OvenPeelMaker.woodStock = 18; OvenPeelMaker.leatherStock = 10; OvenPeelMaker.silverStock = 8; OvenPeelMaker.goldStock = 6; OvenPeelMaker.jewelStock = 4; OvenPeelMaker.pearlStock = 4
OvenPeelMaker.productStock = {}; OvenPeelMaker.buildings = {}; OvenPeelMaker.maker = nil; OvenPeelMaker.activeMaking = {}; OvenPeelMaker.totalProducts = 0; OvenPeelMaker.dayTimer = 0
function OvenPeelMaker.init() OvenPeelMaker.ironStock=12; OvenPeelMaker.bronzeStock=10; OvenPeelMaker.woodStock=18; OvenPeelMaker.leatherStock=10; OvenPeelMaker.silverStock=8; OvenPeelMaker.goldStock=6; OvenPeelMaker.jewelStock=4; OvenPeelMaker.pearlStock=4; OvenPeelMaker.productStock={}; OvenPeelMaker.buildings={}; OvenPeelMaker.maker=nil; OvenPeelMaker.activeMaking={}; OvenPeelMaker.totalProducts=0; OvenPeelMaker.dayTimer=0; print("[OvenPeelMaker] Royal Oven Peel Maker System initialized (6 products, 4 buildings)") end
function OvenPeelMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; OvenPeelMaker.maker={name=n or ("Lopatar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Lopatar najet: %s (spretnost: %d)",OvenPeelMaker.maker.name,s),"success") end; return true end
function OvenPeelMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function OvenPeelMaker.build(id) local ok,e=OvenPeelMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(OvenPeelMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function OvenPeelMaker.getQualityBonus() local b=0; for _,bd in ipairs(OvenPeelMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function OvenPeelMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and OvenPeelMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and OvenPeelMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and OvenPeelMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and OvenPeelMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and OvenPeelMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and OvenPeelMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and OvenPeelMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and OvenPeelMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #OvenPeelMaker.buildings==0 then return false,"Potrebna lopatna delavnica" end; if not OvenPeelMaker.maker then return false,"Potreben lopatar" end; return true end
function OvenPeelMaker.make(pt,qty) qty=qty or 1; local ok,e=OvenPeelMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then OvenPeelMaker.ironStock=OvenPeelMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then OvenPeelMaker.bronzeStock=OvenPeelMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then OvenPeelMaker.woodStock=OvenPeelMaker.woodStock-d.woodCost*qty end; if d.leatherCost then OvenPeelMaker.leatherStock=OvenPeelMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then OvenPeelMaker.silverStock=OvenPeelMaker.silverStock-d.silverCost*qty end; if d.goldCost then OvenPeelMaker.goldStock=OvenPeelMaker.goldStock-d.goldCost*qty end; if d.jewelCost then OvenPeelMaker.jewelStock=OvenPeelMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then OvenPeelMaker.pearlStock=OvenPeelMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if OvenPeelMaker.maker then t=math.max(1,t-math.floor(OvenPeelMaker.maker.skill/13)) end; table.insert(OvenPeelMaker.activeMaking,{id="${MAKER_LOWER}_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function OvenPeelMaker.completeMaking(m) local q=1.0+(OvenPeelMaker.getQualityBonus()/100); if OvenPeelMaker.maker then q=q+(OvenPeelMaker.maker.skill/140) end; q=math.min(2.5,q); OvenPeelMaker.productStock[m.productType]=(OvenPeelMaker.productStock[m.productType] or 0)+m.quantity; OvenPeelMaker.totalProducts=OvenPeelMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if OvenPeelMaker.maker then OvenPeelMaker.maker.itemsMade=OvenPeelMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then OvenPeelMaker.maker.skill=math.min(100,OvenPeelMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Lopata izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"${MAKER_LOWER}.completed",{productName=m.productName,prestige=m.prestige,happiness:m.happiness}) end end
function OvenPeelMaker.update(dt) if not _G.state then return end; OvenPeelMaker.dayTimer=OvenPeelMaker.dayTimer+dt; if OvenPeelMaker.dayTimer>=30 then OvenPeelMaker.dayTimer=0; for i=#OvenPeelMaker.activeMaking,1,-1 do local m=OvenPeelMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then OvenPeelMaker.completeMaking(m); table.remove(OvenPeelMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(OvenPeelMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if OvenPeelMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function OvenPeelMaker.getStats() return {ironStock=OvenPeelMaker.ironStock,bronzeStock=OvenPeelMaker.bronzeStock,woodStock=OvenPeelMaker.woodStock,leatherStock=OvenPeelMaker.leatherStock,silverStock=OvenPeelMaker.silverStock,goldStock=OvenPeelMaker.goldStock,jewelStock=OvenPeelMaker.jewelStock,pearlStock=OvenPeelMaker.pearlStock,productStock=OvenPeelMaker.productStock,numBuildings=#OvenPeelMaker.buildings,hasMaker=OvenPeelMaker.maker~=nil,makerName=OvenPeelMaker.maker and OvenPeelMaker.maker.name or "—",makerSkill=OvenPeelMaker.maker and OvenPeelMaker.maker.skill or 0,activeMaking=#OvenPeelMaker.activeMaking,totalProducts=OvenPeelMaker.totalProducts} end
return OvenPeelMaker
